BEGIN;
ALTER TABLE documentation_pages ADD COLUMN IF NOT EXISTS parent_id uuid REFERENCES documentation_pages(id);
ALTER TABLE documentation_versions ADD COLUMN IF NOT EXISTS metadata jsonb;
CREATE TABLE IF NOT EXISTS documentation_assets(id uuid PRIMARY KEY,pathname text UNIQUE NOT NULL,mime text NOT NULL,size integer NOT NULL,width integer NOT NULL,height integer NOT NULL,digest text NOT NULL,creator_id uuid REFERENCES users(id),page_id uuid REFERENCES documentation_pages(id),state text NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','deleted')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documentation_asset_refs(asset_id uuid REFERENCES documentation_assets(id),page_id uuid NOT NULL,revision integer NOT NULL,PRIMARY KEY(asset_id,page_id,revision),FOREIGN KEY(page_id,revision) REFERENCES documentation_versions(page_id,revision) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documentation_drafts(user_id uuid REFERENCES users(id) ON DELETE CASCADE,page_key text NOT NULL,payload jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,page_key));
CREATE TABLE IF NOT EXISTS documentation_draft_assets(user_id uuid,page_key text,asset_id uuid REFERENCES documentation_assets(id),PRIMARY KEY(user_id,page_key,asset_id),FOREIGN KEY(user_id,page_key) REFERENCES documentation_drafts(user_id,page_key) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documentation_events(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),page_id uuid REFERENCES documentation_pages(id),action text NOT NULL,revision integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS documentation_asset_refs_page ON documentation_asset_refs(page_id,revision);
CREATE INDEX IF NOT EXISTS documentation_pages_parent ON documentation_pages(parent_id);
COMMIT;
